const b = $('Webhook Alta Cliente').first().json.body || {};
const negocio = String(b.negocio || '').trim();
if (!negocio) { return [{ json: { ok: false, b64: '', error: 'no_negocio' } }]; }
const servicios = Array.isArray(b.servicios) ? b.servicios : [];
const notas = [
  'Alta de cliente via forms.',
  'Servicios: ' + servicios.map(s => (s.nombre || '') + (s.precio ? ' Bs ' + s.precio : '')).join(' | '),
  'La web debe: ' + (Array.isArray(b.objetivo_web) ? b.objetivo_web.join(', ') : ''),
  'Atiende WhatsApp: ' + (b.quien_atiende || '-'),
].join('\n');
const lead = {
  company: negocio,
  contact: [b.contacto_nombre, b.whatsapp, b.email].filter(Boolean).join(' - '),
  channel: 'Alta cliente',
  source: 'alta-form',
  pipeline_status: 'Ganado',
  business_type: b.rubro || 'pendiente',
  notes: notas.slice(0, 2000),
  alta: b,
};
const b64 = Buffer.from(JSON.stringify(lead)).toString('base64');
return [{ json: { ok: true, b64: b64 } }];

const b = $('Webhook Alta Cliente').first().json.body || {};
let ins = { ok: false, error: 'sin salida del insert' };
try { ins = JSON.parse(String($input.first().json.stdout || '').trim().split('\n').pop()); } catch (e) { ins = { ok: false, error: 'parse stdout' }; }
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const li = (k, v) => v ? '<b>' + k + ':</b> ' + esc(v) + '<br>' : '';
const h3 = (t) => '<h3 style="border-bottom:2px solid #1e5bff;padding-bottom:4px">' + t + '</h3>';
const servicios = (Array.isArray(b.servicios) ? b.servicios : []).map(s => '&bull; ' + esc(s.nombre) + (s.precio ? ' &mdash; Bs ' + esc(s.precio) : '')).join('<br>');
const faqs = (Array.isArray(b.faqs) ? b.faqs : []).map(f => '&bull; ' + esc(f.pregunta) + '<br>&nbsp;&nbsp;&rarr; ' + esc(f.respuesta)).join('<br>');
const estado = ins.ok ? 'Guardado en el CRM (' + esc(ins.lead_key) + ')' : 'NO se guardo en el CRM: ' + esc(ins.error || 'error desconocido');
const html = '<div style="font-family:Arial,sans-serif;color:#101827;max-width:640px">' +
  '<h2 style="color:#1e5bff;margin:0 0 4px">Alta de cliente &mdash; ONIA</h2>' +
  '<p style="color:' + (ins.ok ? '#0f8b62' : '#b23c3c') + ';font-weight:bold">' + estado + '</p>' +
  h3('Negocio') + '<p>' + li('Negocio', b.negocio) + li('Rubro', b.rubro) + li('Ciudad', b.ciudad) + li('NIT', b.nit) + li('Contacto', b.contacto_nombre) + li('WhatsApp', b.whatsapp) + li('Correo', b.email) + '</p>' +
  h3('Para el bot') + '<p>' + (servicios ? '<b>Servicios:</b><br>' + servicios + '<br>' : '') + li('Horarios', b.horarios) + li('Direccion', b.direccion) + li('Tono', b.tono) + (faqs ? '<b>Preguntas frecuentes:</b><br>' + faqs + '<br>' : '') + '</p>' +
  h3('Para la web') + '<p>' + li('Logo', b.tiene_logo) + li('Fotos', b.tiene_fotos) + li('Colores', b.colores) + li('Redes', b.redes) + li('La web debe', (b.objetivo_web || []).join(', ')) + '</p>' +
  h3('Operacion') + '<p>' + li('Cobra por', (b.como_cobra || []).join(', ')) + li('Atiende WhatsApp', b.quien_atiende) + li('Extra', b.extra) + '</p>' +
  '</div>';
const subject = 'Alta de cliente - ' + (b.negocio || 'sin nombre') + ' (' + (b.rubro || 'sin rubro') + ')' + (ins.ok ? '' : ' [ERROR CRM]');
return [{ json: { subject: subject, html: html, insert_ok: Boolean(ins.ok), lead_key: ins.lead_key || null } }];
